import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"组合式设计（组合优于继承）","description":"","frontmatter":{},"headers":[],"relativePath":"evolution/composition-over-inheritance.md","filePath":"evolution/composition-over-inheritance.md","lastUpdated":1791561689000}`),a={name:`evolution/composition-over-inheritance.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="组合式设计-组合优于继承" tabindex="-1">组合式设计（组合优于继承） <a class="header-anchor" href="#组合式设计-组合优于继承" aria-label="Permalink to “组合式设计（组合优于继承）”">​</a></h1><p>组合式设计指&quot;用对象之间的持有关系拼出行为，而不是用类之间的继承关系拼出行为&quot;。GoF 在书里就写下了这条原则：优先使用对象组合而非类继承 [S1]。它的现代形态不是一句口号，而是三种语言给出的同一套写法：Go 用结构体嵌入，Vue 用组合式 API [S22]，React 用组件嵌套与自定义 Hook [S23]。</p><h2 id="继承的两个结构性问题" tabindex="-1">继承的两个结构性问题 <a class="header-anchor" href="#继承的两个结构性问题" aria-label="Permalink to “继承的两个结构性问题”">​</a></h2><ol><li><strong>编译期就焊死</strong>：子类在类声明处选定父类，运行时换不了。要&quot;换一个能力&quot;就得换类、重新实例化，<a href="/hello-design-patterns/behavioral/strategy">策略模式</a>想做的事情做不到。</li><li><strong>耦合扩散</strong>：父类改一个 protected 方法的语义，所有子类一起受影响，而编译器不会告诉你哪些子类依赖了这条语义。用组合时，改动只波及直接持有它的对象。</li></ol><p>白盒复用（继承，子类能看到父类实现）省事在前，代价在后；黑盒复用（组合，只通过接口协作）前期多写几个转发方法，换来实现可换、可单独测试。</p><h2 id="三种语言的写法" tabindex="-1">三种语言的写法 <a class="header-anchor" href="#三种语言的写法" aria-label="Permalink to “三种语言的写法”">​</a></h2><h3 id="go-嵌入与小接口" tabindex="-1">Go：嵌入与小接口 <a class="header-anchor" href="#go-嵌入与小接口" aria-label="Permalink to “Go：嵌入与小接口”">​</a></h3><p>Go 没有继承，<code>struct</code> 嵌入直接提供方法提升（promoted methods），行为拼装靠接口组合：</p><div class="language-go line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">go</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> Reader</span><span style="color:#F97583;"> interface</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#B392F0;">    Read</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">p</span><span style="color:#E1E4E8;"> []</span><span style="color:#F97583;">byte</span><span style="color:#E1E4E8;">) (</span><span style="color:#F97583;">int</span><span style="color:#E1E4E8;">, </span><span style="color:#F97583;">error</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> CountingReader</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#B392F0;">    Reader</span><span style="color:#818e99;">                 // 嵌入接口，拿到 Read 的能力</span></span>
<span class="line"><span style="color:#E1E4E8;">    n </span><span style="color:#F97583;">int64</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#E1E4E8;"> (</span><span style="color:#FFAB70;">c </span><span style="color:#F97583;">*</span><span style="color:#B392F0;">CountingReader</span><span style="color:#E1E4E8;">) </span><span style="color:#B392F0;">Read</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">p</span><span style="color:#E1E4E8;"> []</span><span style="color:#F97583;">byte</span><span style="color:#E1E4E8;">) (</span><span style="color:#F97583;">int</span><span style="color:#E1E4E8;">, </span><span style="color:#F97583;">error</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#E1E4E8;">    n, err </span><span style="color:#F97583;">:=</span><span style="color:#E1E4E8;"> c.Reader.</span><span style="color:#B392F0;">Read</span><span style="color:#E1E4E8;">(p)</span></span>
<span class="line"><span style="color:#E1E4E8;">    c.n </span><span style="color:#F97583;">+=</span><span style="color:#F97583;"> int64</span><span style="color:#E1E4E8;">(n)</span></span>
<span class="line"><span style="color:#F97583;">    return</span><span style="color:#E1E4E8;"> n, err</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#E1E4E8;"> (</span><span style="color:#FFAB70;">c </span><span style="color:#F97583;">*</span><span style="color:#B392F0;">CountingReader</span><span style="color:#E1E4E8;">) </span><span style="color:#B392F0;">BytesRead</span><span style="color:#E1E4E8;">() </span><span style="color:#F97583;">int64</span><span style="color:#E1E4E8;"> { </span><span style="color:#F97583;">return</span><span style="color:#E1E4E8;"> c.n }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p><code>CountingReader</code> 可以包任何 <code>Reader</code>，也可以在运行时换掉被包装的对象。这是装饰、代理、适配器三种模式在 Go 里的统一形态：站内这三篇的 Go 示例都是接口加结构体持有的组合写法，只是有的用字段持有、没有用嵌入。</p><h3 id="vue-组合式-api" tabindex="-1">Vue：组合式 API <a class="header-anchor" href="#vue-组合式-api" aria-label="Permalink to “Vue：组合式 API”">​</a></h3><p>选项式 API 按选项分（<code>data</code>、<code>methods</code>、<code>watch</code> 分开写），同一个功能的代码散在四处；组合式 API 按功能收（[S22]）：</p><div class="language-js line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> { ref, onMounted } </span><span style="color:#F97583;">from</span><span style="color:#9ECBFF;"> &#39;vue&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">export</span><span style="color:#F97583;"> function</span><span style="color:#B392F0;"> useOrders</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">fetcher</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#F97583;">  const</span><span style="color:#79B8FF;"> list</span><span style="color:#F97583;"> =</span><span style="color:#B392F0;"> ref</span><span style="color:#E1E4E8;">([])</span></span>
<span class="line"><span style="color:#F97583;">  const</span><span style="color:#79B8FF;"> loading</span><span style="color:#F97583;"> =</span><span style="color:#B392F0;"> ref</span><span style="color:#E1E4E8;">(</span><span style="color:#79B8FF;">false</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">  async</span><span style="color:#F97583;"> function</span><span style="color:#B392F0;"> load</span><span style="color:#E1E4E8;">() {</span></span>
<span class="line"><span style="color:#E1E4E8;">    loading.value </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> true</span></span>
<span class="line"><span style="color:#F97583;">    try</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">      list.value </span><span style="color:#F97583;">=</span><span style="color:#F97583;"> await</span><span style="color:#B392F0;"> fetcher</span><span style="color:#E1E4E8;">()</span></span>
<span class="line"><span style="color:#E1E4E8;">    } </span><span style="color:#F97583;">finally</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">      loading.value </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> false</span></span>
<span class="line"><span style="color:#E1E4E8;">    }</span></span>
<span class="line"><span style="color:#E1E4E8;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#B392F0;">  onMounted</span><span style="color:#E1E4E8;">(load)</span></span>
<span class="line"><span style="color:#F97583;">  return</span><span style="color:#E1E4E8;"> { list, loading, load }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// 组件里</span></span>
<span class="line"><span style="color:#F97583;">const</span><span style="color:#E1E4E8;"> { </span><span style="color:#79B8FF;">list</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">loading</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">load</span><span style="color:#E1E4E8;"> } </span><span style="color:#F97583;">=</span><span style="color:#B392F0;"> useOrders</span><span style="color:#E1E4E8;">(api.fetchOrders)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>复用单元是一个函数，返回值组合进组件；换数据源就换参数，不改组件。对比 mixin：mixin 的状态与生命周期按合并规则混入，来源看不出来，函数返回值则是显式的。</p><h3 id="react-组件嵌套与自定义-hook" tabindex="-1">React：组件嵌套与自定义 Hook <a class="header-anchor" href="#react-组件嵌套与自定义-hook" aria-label="Permalink to “React：组件嵌套与自定义 Hook”">​</a></h3><p>React 的官方文档把&quot;组合&quot;放在组件设计的核心位置 [S23]：UI 用组件嵌套加 props 拼，重复逻辑用自定义 Hook 收口，状态不够用就状态提升：</p><div class="language-jsx line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">jsx</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">function</span><span style="color:#B392F0;"> Page</span><span style="color:#E1E4E8;">({ </span><span style="color:#FFAB70;">user</span><span style="color:#E1E4E8;"> }) {</span></span>
<span class="line"><span style="color:#F97583;">  return</span><span style="color:#E1E4E8;"> (</span></span>
<span class="line"><span style="color:#E1E4E8;">    &lt;</span><span style="color:#79B8FF;">Panel</span><span style="color:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="color:#E1E4E8;">      &lt;</span><span style="color:#79B8FF;">Greeting</span><span style="color:#B392F0;"> name</span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;">{user.name} /&gt;</span></span>
<span class="line"><span style="color:#E1E4E8;">      &lt;</span><span style="color:#79B8FF;">UserAvatar</span><span style="color:#B392F0;"> user</span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;">{user} /&gt;</span></span>
<span class="line"><span style="color:#E1E4E8;">    &lt;/</span><span style="color:#79B8FF;">Panel</span><span style="color:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="color:#E1E4E8;">  );</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">function</span><span style="color:#B392F0;"> useOrders</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">fetcher</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#F97583;">  const</span><span style="color:#E1E4E8;"> [</span><span style="color:#79B8FF;">list</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">setList</span><span style="color:#E1E4E8;">] </span><span style="color:#F97583;">=</span><span style="color:#B392F0;"> useState</span><span style="color:#E1E4E8;">([]);</span></span>
<span class="line"><span style="color:#B392F0;">  useEffect</span><span style="color:#E1E4E8;">(() </span><span style="color:#F97583;">=&gt;</span><span style="color:#E1E4E8;"> { </span><span style="color:#B392F0;">fetcher</span><span style="color:#E1E4E8;">().</span><span style="color:#B392F0;">then</span><span style="color:#E1E4E8;">(setList); }, [fetcher]);</span></span>
<span class="line"><span style="color:#F97583;">  return</span><span style="color:#E1E4E8;"> list;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p><code>Panel</code>、<code>Greeting</code>、<code>UserAvatar</code> 互不依赖，只依赖 props；<code>useOrders</code> 返回值进组件，没有隐式注入。React 官方明确不推荐用继承复用组件逻辑，理由与 GoF 一致。</p><h2 id="什么时候该用继承" tabindex="-1">什么时候该用继承 <a class="header-anchor" href="#什么时候该用继承" aria-label="Permalink to “什么时候该用继承”">​</a></h2><p>三条可以留继承的情况：</p><ol><li><strong>确实存在&quot;是一个&quot;关系且实现也一样</strong>：<code>ArrayList</code> 是 <code>List</code> 的一种，这种时候继承表达的是类型关系，不是复用手段。</li><li><strong>框架约束</strong>：模板方法模式要求子类覆盖某些步骤，<a href="/hello-design-patterns/behavioral/template-method">模板方法</a>必须用继承，这是它自己付出的代价，站内该篇写了怎么控制。</li><li><strong>类库的公开 API 已经定型</strong>：改成组合会破坏既有调用方，按兼容性优先。</li></ol><p>Go 的 <code>embed</code> 与 C++ 的私有继承（&quot;用它实现&quot;而非&quot;是它一种&quot;）说明：继承的类型含义和复用含义可以分开用，只有把两者混在一起时才危险。</p><h2 id="走出来的顺序" tabindex="-1">走出来的顺序 <a class="header-anchor" href="#走出来的顺序" aria-label="Permalink to “走出来的顺序”">​</a></h2><ol><li>找出继承树里&quot;为了复用而存在&quot;的中间层，它没有类型含义，只有代码。</li><li>把中间层的字段与方法搬进一个新类，父类改成持有一个该类型的字段。</li><li>对外暴露的方法改成转发调用，调用方签名不变，先跑通回归。</li><li>需要运行时切换的，把字段类型换成小接口，见<a href="/hello-design-patterns/behavioral/strategy">策略</a>与<a href="/hello-design-patterns/structural/bridge">桥接</a>。</li></ol><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/behavioral/strategy">策略模式</a>、<a href="/hello-design-patterns/behavioral/state">状态模式</a>：组合换掉继承分支的两个典型。</li><li><a href="/hello-design-patterns/structural/decorator">装饰</a>、<a href="/hello-design-patterns/structural/proxy">代理</a>、<a href="/hello-design-patterns/structural/adapter">适配器</a>：组合在结构型上的三种形态，Go 示例同构。</li><li><a href="/hello-design-patterns/behavioral/template-method">模板方法</a>：必须用继承的场景与代价（子类数量增加、易违反 LSP）。</li><li><a href="/hello-design-patterns/evolution/solid">SOLID 与依赖规则</a>：组合替继承之后，依赖方向靠它定。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S1] GoF《Design Patterns》，1994，&quot;优先使用对象组合而非类继承&quot;。</li><li>[S2] 《Head First Design Patterns》第 2 版，2020，组合与继承的取舍章节。</li><li>[S22] Vue.js 官方文档，组合式 API。</li><li>[S23] React 官方文档，组件组合与状态管理。</li><li>[S21] Go 官方文档，Effective Go 的嵌入与接口部分。</li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};